"use client"

// Scratch Card by Louis Studios.
// 200 more hand-made React components at https://studios.lou15.com/?ref=21st-code

import * as React from "react"

export interface ScratchCardProps extends Omit<React.HTMLAttributes<HTMLDivElement>, "children" | "onCopy"> {
  /** The big value printed on the card, e.g. "$50" or "€25". */
  amount?: string
  /** First brand line, top left of the card (bold). */
  brand?: string
  /** Second brand line under the brand name (lighter). */
  tagline?: string
  /** One line of small print above the silver panel. Truncates with an ellipsis when the card is narrow. */
  note?: string
  /** The code hidden under the silver panel. It stays hidden from assistive tech until it is revealed. */
  code?: string
  /** Text printed on the silver panel; it scratches away with the foil. */
  panelLabel?: string
  /** Line under the card before the code is revealed. */
  hint?: string
  /** Line under the card once the code is revealed, shown beside the copy button. */
  readyHint?: string
  /** Visible text on the copy button. */
  copyLabel?: string
  /** Visible text on the copy button after a copy. */
  copiedLabel?: string
  /** Screen reader name of the silver panel before it is revealed (Enter or Space on it reveals the code). */
  revealLabel?: string
  /** Share of the silver panel (0 to 1) that must be scratched before the code counts as revealed. */
  threshold?: number
  /** Controlled reveal. true clears the foil and shows the copy row; false restores a fresh card. Leave undefined for uncontrolled use. */
  revealed?: boolean
  /** Called once when the code is revealed by scratching or by keyboard. */
  onReveal?: () => void
  /** Called with the code after the copy button wrote it to the clipboard. */
  onCopy?: (code: string) => void
  /** How long the button reads "Copied" before it returns, in ms. 0 keeps it. */
  copiedDuration?: number
  /** The coin scratches the card by itself on a seamless 10 s loop (for previews). Any real pointer press takes over. */
  autoplay?: boolean
  /** Card colour. */
  color?: string
  /** Text and mark colour on the card. */
  ink?: string
  /** Base colour of the brushed silver foil; its sheen and streaks are derived from it. */
  foil?: string
  /** Colour of the strip under the foil that carries the code. */
  paper?: string
  /** Base colour of the gold coin; rim, highlight and engraving are derived from it. */
  coin?: string
  /** Page colour behind the card. */
  background?: string
  /** Dark colour for the code, the hint text and the copy button. */
  textColor?: string
  /** Copy button colour after a successful copy. */
  success?: string
  /** Font stack for the brand, small print, panel label, hint and button. */
  font?: string
  /** Font stack for the big amount (a heavy condensed face reads best). */
  amountFont?: string
  /** Font stack for the code (monospace). */
  codeFont?: string
  /** Largest card width in px. The card scales down to fit its container. */
  cardWidth?: number
}

