// The card is designed at 596 x 375 px (the reference size) and every measure below is in those
// design pixels, multiplied by one scale at render time.
const CW = 596
const CH = 375
const CARD_R = 15
const PAD = 30
const PANEL_Y = 265
const PANEL_H = 79
const PANEL_R = 9
const PANEL_W = CW - PAD * 2
// Where the hint row sits under the card, and the room it needs.
const HINT_Y = CH + 82
const READY_Y = CH + 93.5
const BELOW = 122
// The coin: diameter, and how far above the pointer it rides (its lower rim does the scratching).
const COIN_D = 52
const COIN_LIFT = 20
// The coin edge scrapes an ellipse this size, in design px.
const BRUSH_RX = 18
const BRUSH_RY = 10
const STAMP_STEP = 5
// Coverage grid cell, in design px.
const CELL = 3
const GX = Math.ceil(PANEL_W / CELL)
const GY = Math.ceil(PANEL_H / CELL)
// Autoplay loop length, seconds.
const LOOP = 10
const MAX_FLAKES = 1600

type RGB = [number, number, number]

function parseColor(c: string): RGB {
  const s = c.trim()
  if (s[0] === "#") {
    let h = s.slice(1)
    if (h.length === 3 || h.length === 4) h = h.split("").map((x) => x + x).join("")
    const n = parseInt(h.slice(0, 6), 16)
    return [(n >> 16) & 255, (n >> 8) & 255, n & 255]
  }
  const m = s.match(/rgba?\(([^)]+)\)/i)
  if (m) {
    const p = m[1].split(/[\s,/]+/).filter(Boolean).map(parseFloat)
    return [p[0] || 0, p[1] || 0, p[2] || 0]
  }
  const hm = s.match(/hsla?\(([^)]+)\)/i)
  if (hm) {
    const p = hm[1].split(/[\s,/]+/).filter(Boolean).map(parseFloat)
    const h = (((p[0] || 0) % 360) + 360) % 360, sat = (p[1] || 0) / 100, l = (p[2] || 0) / 100
    const k = (n: number) => (n + h / 30) % 12
    const a = sat * Math.min(l, 1 - l)
    const f = (n: number) => l - a * Math.max(-1, Math.min(k(n) - 3, Math.min(9 - k(n), 1)))
    return [f(0) * 255, f(8) * 255, f(4) * 255]
  }
  return [128, 128, 128] // ls:keep
}

const WHITE: RGB = [255, 255, 255] // ls:keep
const BLACK: RGB = [0, 0, 0] // ls:keep
const mix = (a: RGB, b: RGB, t: number): RGB => [a[0] + (b[0] - a[0]) * t, a[1] + (b[1] - a[1]) * t, a[2] + (b[2] - a[2]) * t]
const css = (c: RGB, a = 1) =>
  a >= 1
    ? `rgb(${Math.round(c[0])}, ${Math.round(c[1])}, ${Math.round(c[2])})`
    : `rgba(${Math.round(c[0])}, ${Math.round(c[1])}, ${Math.round(c[2])}, ${a.toFixed(3)})`

function mulberry(seed: number) {
  let a = seed >>> 0
  return () => {
    a = (a + 0x6d2b79f5) >>> 0
    let t = a
    t = Math.imul(t ^ (t >>> 15), t | 1)
    t ^= t + Math.imul(t ^ (t >>> 7), t | 61)
    return ((t ^ (t >>> 14)) >>> 0) / 4294967296
  }
}

function hash2(x: number, y: number) {
  let h = (x * 374761393 + y * 668265263) | 0
  h = Math.imul(h ^ (h >>> 13), 1274126177)
  return ((h ^ (h >>> 16)) >>> 0) / 4294967296
}

function vnoise(x: number, y: number) {
  const xi = Math.floor(x), yi = Math.floor(y)
  const xf = x - xi, yf = y - yi
  const u = xf * xf * (3 - 2 * xf), v = yf * yf * (3 - 2 * yf)
  const a = hash2(xi, yi), b = hash2(xi + 1, yi), c = hash2(xi, yi + 1), d = hash2(xi + 1, yi + 1)
  return a + (b - a) * u + (c - a) * v + (a - b - c + d) * u * v
}

const easeOut = (t: number) => 1 - Math.pow(1 - t, 3)
const easeInOut = (t: number) => (t < 0.5 ? 4 * t * t * t : 1 - Math.pow(-2 * t + 2, 3) / 2)
const clamp = (v: number, a: number, b: number) => (v < a ? a : v > b ? b : v)

/** The brushed silver foil, painted once per size and colour. */
function paintFoil(w: number, h: number, dpr: number, s: number, foil: RGB, label: string, font: string) {
  const W = Math.max(1, Math.round(w * dpr)), H = Math.max(1, Math.round(h * dpr))
  const cv = document.createElement("canvas")
  cv.width = W
  cv.height = H
  const ctx = cv.getContext("2d")
  if (!ctx) return cv
  // Sheen across the panel, sampled from the reference: two bright bands and a darker right edge.
  const stops: [number, RGB][] = [
    [0, mix(foil, BLACK, 0.03)],
    [0.3, mix(foil, WHITE, 0.44)],
    [0.52, mix(foil, BLACK, 0.025)],
    [0.76, mix(foil, WHITE, 0.32)],
    [1, mix(foil, BLACK, 0.1)],
  ]
  const ramp: RGB[] = []
  for (let x = 0; x < W; x++) {
    const u = x / Math.max(1, W - 1)
    let i = 0
    while (i < stops.length - 2 && u > stops[i + 1][0]) i++
    const [u0, c0] = stops[i], [u1, c1] = stops[i + 1]
    const t = clamp((u - u0) / (u1 - u0), 0, 1)
    ramp.push(mix(c0, c1, 0.5 - 0.5 * Math.cos(Math.PI * t)))
  }
  const img = ctx.createImageData(W, H)
  const d = img.data
  const k = 1 / (dpr * s)
  for (let y = 0; y < H; y++) {
    const yy = y * k
    for (let x = 0; x < W; x++) {
      const xx = x * k
      // Brushed grain: fine horizontal streaks that ripple gently, as on the reference.
      const wy = yy + 0.9 * Math.sin(xx * 0.16 + yy * 0.3) + 0.6 * Math.sin(xx * 0.047 - yy * 0.21)
      const fine = vnoise(xx * 0.05, wy * 0.85) - 0.5
      const mid = vnoise(xx * 0.03 + 40, wy * 0.28) - 0.5
      const g = 1 + fine * 0.026 + mid * 0.04
      const c = ramp[x]
      const o = (y * W + x) * 4
      d[o] = clamp(c[0] * g, 0, 255)
      d[o + 1] = clamp(c[1] * g, 0, 255)
      d[o + 2] = clamp(c[2] * g, 0, 255)
      d[o + 3] = 255
    }
  }
  ctx.putImageData(img, 0, 0)
  // A hairline light rim along the top and a faint shade along the bottom give the foil its edge.
  ctx.fillStyle = css(mix(foil, WHITE, 0.5), 0.55)
  ctx.fillRect(0, 0, W, Math.max(1, Math.round(dpr * 0.75)))
  ctx.fillStyle = css(mix(foil, BLACK, 0.2), 0.25)
  ctx.fillRect(0, H - Math.max(1, Math.round(dpr * 0.75)), W, Math.max(1, Math.round(dpr * 0.75)))
  if (label) {
    ctx.save()
    ctx.scale(dpr, dpr)
    ctx.fillStyle = css(mix(foil, BLACK, 0.53))
    ctx.font = `600 ${Math.max(11, 15.5 * s)}px ${font}`
    ctx.textAlign = "center"
    ctx.textBaseline = "middle"
    ctx.fillText(label, w / 2, h / 2 + 0.5 * s, w - 16)
    ctx.restore()
  }
  return cv
}

/** Brush sprites: an elliptical scrape with a grainy, torn edge. */
function paintBrushes(dpr: number, s: number) {
  const out: HTMLCanvasElement[] = []
  const rx = BRUSH_RX * s * dpr, ry = BRUSH_RY * s * dpr
  const W = Math.ceil(rx * 2) + 4, H = Math.ceil(ry * 2) + 4
  for (let v = 0; v < 4; v++) {
    const cv = document.createElement("canvas")
    cv.width = W
    cv.height = H
    const ctx = cv.getContext("2d")
    if (!ctx) continue
    const img = ctx.createImageData(W, H)
    const d = img.data
    const g = 1 / (dpr * s)
    for (let y = 0; y < H; y++) {
      for (let x = 0; x < W; x++) {
        const nx = (x - W / 2) / rx, ny = (y - H / 2) / ry
        const r = Math.sqrt(nx * nx + ny * ny)
        // Torn edge: coarse lumps plus per-grain speckle, so overlapping stamps leave grit at the rim.
        const lump = vnoise(x * g * 0.18 + v * 31, y * g * 0.3 + v * 17) - 0.5
        const grain = hash2(Math.floor(x * g * 1.3) + v * 997, Math.floor(y * g * 1.3)) - 0.5
        const e = r + lump * 0.26 + grain * 0.16
        const a = clamp((1 - e) / 0.24, 0, 1) * (0.9 + 0.1 * (vnoise(x * g * 0.5 + v * 7, y * g * 0.9) > 0.35 ? 1 : 0.4))
        const o = (y * W + x) * 4
        d[o] = d[o + 1] = d[o + 2] = 255
        d[o + 3] = Math.round(a * 255)
      }
    }
    ctx.putImageData(img, 0, 0)
    out.push(cv)
  }
  return out
}

interface Flake {
  x: number
  y: number
  vx: number
  vy: number
  r: number
  vr: number
  len: number
  w: number
  col: string
  age: number
  rest: boolean
  fade: number
}

interface Stamp {
  x: number
  y: number
  v: number
  r: number
}

interface Anim {
  v: number
  from: number
  to: number
  t0: number
  dur: number
  io?: boolean
}

const useIso = typeof window === "undefined" ? React.useEffect : React.useLayoutEffect

// The autoplay script: the pointer path in card design px, with presses. The pointer is the
// coin's scraping edge; the coin floats just above it.
const AUTO_PATH: [number, number, number][] = [
  // t, x, y
  [0.0, 330, 470],
  [0.55, 300, 400],
  [0.95, 150, 318],
  [1.25, 96, 300],
  [1.55, 250, 312],
  [1.75, 168, 296],
  [2.0, 360, 318],
  [2.2, 262, 328],
  [2.45, 452, 300],
  [2.65, 350, 292],
  [2.9, 520, 316],
  [3.1, 420, 330],
  [3.35, 230, 318],
  [3.55, 120, 326],
  [3.8, 300, 300],
  [4.0, 210, 288],
  [4.25, 410, 306],
  [4.45, 500, 296],
  [4.75, 470, 360],
  [5.15, 455, 455],
  [5.6, 440, 470],
  [10.0, 330, 470],
]
const AUTO_DOWN: [number, number] = [1.25, 4.5]
const AUTO_COPY = 5.55
const AUTO_RESET = 8.5
const RESET_DUR = 1.0

function autoPoint(t: number): [number, number] {
  const P = AUTO_PATH
  let i = 0
  while (i < P.length - 2 && t > P[i + 1][0]) i++
  const a = P[Math.max(0, i - 1)], b = P[i], c = P[i + 1], d = P[Math.min(P.length - 1, i + 2)]
  const u = clamp((t - b[0]) / (c[0] - b[0]), 0, 1)
  // Catmull-Rom through the script points, for a hand-like curve.
  const cr = (p0: number, p1: number, p2: number, p3: number) =>
    0.5 * (2 * p1 + (-p0 + p2) * u + (2 * p0 - 5 * p1 + 4 * p2 - p3) * u * u + (-p0 + 3 * p1 - 3 * p2 + p3) * u * u * u)
  return [cr(a[1], b[1], c[1], d[1]), cr(a[2], b[2], c[2], d[2])]
}

export function ScratchCard({
  amount = "$50",
  brand = "Louis Studios",
  tagline = "Component studio",
  note = "Studio gift card. Spend it on components or a plan.",
  code = "DEMO-LS50-GIFT",
  panelLabel = "Scratch here with a coin",
  hint = "Scratch the silver panel to reveal your code",
  readyHint = "Your code is ready.",
  copyLabel = "Copy code",
  copiedLabel = "Copied",
  revealLabel = "Reveal code",
  threshold = 0.415,
  revealed,
  onReveal,
  onCopy,
  copiedDuration = 2600,
  autoplay = false,
  color = "#d2352c",
  ink = "#fdf1e0",
  foil = "#c8c9d3",
  paper = "#faf4ec",
  coin = "#e9cf6c",
  background = "#d6cfc8",
  textColor = "#1a1612",
  success = "#1f8342",
  font = UI_FONT,
  amountFont = AMOUNT_FONT,
  codeFont = CODE_FONT,
  cardWidth = 596,
  className,
  style,
  ...rest
}: ScratchCardProps) {
  const uid = React.useId().replace(/[^a-zA-Z0-9]/g, "")
  const rootRef = React.useRef<HTMLDivElement>(null)
  const cardRef = React.useRef<HTMLDivElement>(null)
  const panelRef = React.useRef<HTMLDivElement>(null)
  const foilRef = React.useRef<HTMLCanvasElement>(null)
  const flakeRef = React.useRef<HTMLCanvasElement>(null)
  const coinRef = React.useRef<HTMLDivElement>(null)
  const hintRef = React.useRef<HTMLDivElement>(null)
  const readyRef = React.useRef<HTMLDivElement>(null)
  const btnRef = React.useRef<HTMLButtonElement>(null)
  const lab1Ref = React.useRef<HTMLSpanElement>(null)
  const lab2Ref = React.useRef<HTMLSpanElement>(null)

  const [box, setBox] = React.useState({ w: 0, h: 0 })
  const [shown, setShown] = React.useState(false)
  const [copied, setCopied] = React.useState(false)
  const [copyTick, setCopyTick] = React.useState(0)
  const isRevealed = revealed ?? shown

  // Layout: one scale for the whole card, so it stays the reference's proportions at any size.
  const W = box.w, H = box.h
  const s = W && H ? Math.max(0.3, Math.min(cardWidth / CW, (W - 32) / CW, (H - 24) / (CH + BELOW * 2 - 70))) : 1
  const cw = CW * s, ch = CH * s
  const cx = (W - cw) / 2
  const cy = Math.max(12, Math.min((H - ch) / 2 - 4 * s, H - ch - BELOW * s - 4))

  const geo = React.useRef({ s, cx, cy })
  geo.current = { s, cx, cy }
  const props = React.useRef({ threshold, onReveal, autoplay, color, ink, foil, coin, textColor, success, code, controlled: revealed !== undefined })
  props.current = { threshold, onReveal, autoplay, color, ink, foil, coin, textColor, success, code, controlled: revealed !== undefined }

  // The engine: all moving parts live here, outside React, on one requestAnimationFrame loop.
  const eng = React.useRef<any>(null)
  if (!eng.current) {
    eng.current = {
      stamps: [] as Stamp[],
      grid: new Uint8Array(GX * GY),
      covered: 0,
      flakes: [] as Flake[],
      rng: mulberry(7),
      ptr: { x: 0, y: 0, in: false, down: false, kind: "mouse", vx: 0, last: 0, has: false },
      coin: { x: 0, y: 0, rot: 0, press: 0 },
      anims: {} as Record<string, Anim>,
      started: false,
      revealed: false,
      copied: false,
      full: false,
      reset: -1,
      auto: { on: false, t: 0, user: false, wasDown: false, copied: false },
      kick: () => {},
      dirty: true,
      flakesDirty: true,
      texture: null as HTMLCanvasElement | null,
      mask: null as HTMLCanvasElement | null,
      brushes: [] as HTMLCanvasElement[],
      reduced: false,
      setShown: setShown,
      setCopied: setCopied,
    }
  }

  useIso(() => {
    const el = rootRef.current
    if (!el) return
    const measure = () => {
      const r = el.getBoundingClientRect()
      setBox((b) => (Math.abs(b.w - r.width) < 0.5 && Math.abs(b.h - r.height) < 0.5 ? b : { w: r.width, h: r.height }))
    }
    measure()
    const ro = new ResizeObserver(measure)
    ro.observe(el)
    return () => ro.disconnect()
  }, [])

  // Foil texture, mask and brushes are rebuilt when the size or the look changes; the scratches
  // are kept as stamps in design px and replayed, so a resize never loses them.
  const [dprTick, setDprTick] = React.useState(0)
  React.useEffect(() => {
    if (typeof window === "undefined" || !window.matchMedia) return
    const mq = window.matchMedia(`(resolution: ${window.devicePixelRatio || 1}dppx)`)
    const on = () => setDprTick((n) => n + 1)
    mq.addEventListener?.("change", on)
    return () => mq.removeEventListener?.("change", on)
  }, [dprTick])

  useIso(() => {
    const E = eng.current
    const fc = foilRef.current
    if (!fc || !W) return
    const dpr = Math.min(3, window.devicePixelRatio || 1)
    const pw = PANEL_W * s, ph = PANEL_H * s
    fc.width = Math.round(pw * dpr)
    fc.height = Math.round(ph * dpr)
    E.dpr = dpr
    E.texture = paintFoil(pw, ph, dpr, s, parseColor(foil), panelLabel, font)
    E.brushes = paintBrushes(dpr, s)
    const m = E.mask || document.createElement("canvas")
    m.width = fc.width
    m.height = fc.height
    E.mask = m
    const mctx = m.getContext("2d")
    if (mctx && E.drawStamp) {
      mctx.clearRect(0, 0, m.width, m.height)
      for (const st of E.stamps) E.drawStamp(st, mctx)
    }
    const flc = flakeRef.current
    if (flc) {
      flc.width = Math.round(W * dpr)
      flc.height = Math.round(H * dpr)
    }
    E.dirty = true
    E.flakesDirty = true
    E.kick()
  }, [W, H, s, foil, panelLabel, font, dprTick])

  React.useEffect(() => {
    const E = eng.current
    const root = rootRef.current
    if (!root) return
    const now = () => performance.now()
    E.reduced = !!window.matchMedia?.("(prefers-reduced-motion: reduce)").matches
    const mq = window.matchMedia?.("(prefers-reduced-motion: reduce)")
    const onMq = () => {
      E.reduced = mq.matches
    }
    mq?.addEventListener?.("change", onMq)

    const anim = (k: string, to: number, dur: number, io = false) => {
      const a: Anim = E.anims[k] || (E.anims[k] = { v: to, from: to, to, t0: 0, dur: 1 })
      if (a.to === to) return
      a.from = a.v
      a.to = to
      a.t0 = now()
      a.dur = Math.max(1, dur)
      a.io = io
      E.kick()
    }
    const val = (k: string, init = 0) => (E.anims[k] ? E.anims[k].v : init)
    E.anim = anim
    anim("hint", 1, 1)
    anim("ready", 0, 1)
    anim("copied", 0, 1)
    anim("coin", 0, 1)
    anim("foilA", 1, 1)
    anim("maskA", 1, 1)
    for (const k in E.anims) E.anims[k].v = E.anims[k].to

    E.drawStamp = (st: Stamp, ctx: CanvasRenderingContext2D) => {
      const b = E.brushes[st.v % Math.max(1, E.brushes.length)]
      if (!b) return
      const k = geo.current.s * E.dpr
      ctx.setTransform(1, 0, 0, 1, st.x * k, st.y * k)
      ctx.rotate(st.r)
      ctx.drawImage(b, -b.width / 2, -b.height / 2)
      ctx.setTransform(1, 0, 0, 1, 0, 0)
    }

    const markGrid = (x: number, y: number) => {
      const rx = BRUSH_RX * 0.86, ry = BRUSH_RY * 0.86
      const x0 = Math.max(0, Math.floor((x - rx) / CELL)), x1 = Math.min(GX - 1, Math.floor((x + rx) / CELL))
      const y0 = Math.max(0, Math.floor((y - ry) / CELL)), y1 = Math.min(GY - 1, Math.floor((y + ry) / CELL))
      for (let gy = y0; gy <= y1; gy++) {
        for (let gx = x0; gx <= x1; gx++) {
          const dx = ((gx + 0.5) * CELL - x) / rx, dy = ((gy + 0.5) * CELL - y) / ry
          if (dx * dx + dy * dy <= 1) {
            const i = gy * GX + gx
            if (!E.grid[i]) {
              E.grid[i] = 1
              E.covered++
            }
          }
        }
      }
    }

    const spawnFlakes = (x: number, y: number, dx: number, dy: number, n: number) => {
      if (E.reduced) return
      const rng = E.rng
      const f = parseColor(props.current.foil)
      const len = Math.hypot(dx, dy) || 1
      const ux = dx / len, uy = dy / len
      for (let i = 0; i < n; i++) {
        // Most chips drop beside the stroke; a few are flicked out sideways past the card edge.
        const kind = rng()
        // Half are flicked off the card sideways, a third stop on the red around the panel,
        // the rest drop where they were scraped.
        const fast = kind < 0.55
        const side = rng() < 0.5 + 0.2 * Math.sign(ux || 1) ? 1 : -1
        const ang = (rng() - 0.5) * (fast ? 0.42 : kind < 0.9 ? 2.0 : 3)
        const sp = fast ? 700 + rng() * 900 : kind < 0.9 ? 60 + rng() * 300 : 8 + rng() * 50
        const tone = rng()
        const col =
          tone < 0.45 ? mix(f, BLACK, 0.32 + rng() * 0.16) : tone < 0.8 ? mix(f, BLACK, 0.12 + rng() * 0.12) : mix(f, WHITE, 0.25)
        E.flakes.push({
          x: PAD + x + (rng() - 0.5) * BRUSH_RX * 2,
          y: PANEL_Y + y + (rng() - 0.5) * BRUSH_RY * 2.2,
          vx: Math.cos(ang) * sp * side,
          vy: Math.sin(ang) * sp - 20 * rng(),
          r: rng() * Math.PI,
          vr: (rng() - 0.5) * 22,
          len: 2.4 + rng() * 2.8,
          w: 1.3 + rng() * 0.9,
          col: css(col),
          age: 0,
          rest: false,
          fade: 1,
        })
        void uy
      }
      if (E.flakes.length > MAX_FLAKES) {
        let over = E.flakes.length - MAX_FLAKES
        for (const fl of E.flakes) {
          if (over <= 0) break
          if (fl.fade >= 1 && fl.rest) {
            fl.fade = 0.999
            over--
          }
        }
      }
      E.flakesDirty = true
    }

    // One scrape from the last contact point to this one, in panel design px.
    const scrape = (x0: number, y0: number, x1: number, y1: number, speed = 0) => {
      const mctx = E.mask?.getContext("2d")
      const dx = x1 - x0, dy = y1 - y0
      const dist = Math.hypot(dx, dy)
      // A fast flick leaves a lumpy chain of scrapes, a slow drag one even band.
      const n = Math.max(1, Math.ceil(dist / clamp(speed / 115, STAMP_STEP, 26)))
      const rng = E.rng
      let any = false
      const step = dist / n
      const ux = dist ? dx / dist : 0, uy = dist ? dy / dist : 0
      for (let i = 1; i <= n; i++) {
        const t = i / n
        const x = x0 + dx * t + (rng() - 0.5) * 2, y = y0 + dy * t + (rng() - 0.5) * 6
        if (x < -BRUSH_RX || x > PANEL_W + BRUSH_RX || y < -BRUSH_RY || y > PANEL_H + BRUSH_RY) continue
        const st: Stamp = { x, y, v: Math.floor(rng() * 4), r: (rng() - 0.5) * 0.22 }
        E.stamps.push(st)
        if (mctx) E.drawStamp(st, mctx)
        markGrid(x, y)
        any = true
        // The coin pushes chips already lying in its path, so they pile up on the foil ahead of it.
        const cxp = PAD + x, cyp = PANEL_Y + y
        const push = Math.min(900, speed * 0.7)
        for (const f of E.flakes) {
          if (!f.rest || f.fade < 1) continue
          const ex = (f.x - cxp) / BRUSH_RX, ey = (f.y - cyp) / (BRUSH_RY * 1.2)
          if (ex * ex + ey * ey > 1) continue
          f.rest = false
          f.age = 0.2
          f.vx = ux * push * (0.4 + rng() * 0.8) + (rng() - 0.5) * 60
          f.vy = uy * push * (0.4 + rng() * 0.8) + (rng() - 0.5) * 60
          f.vr = (rng() - 0.5) * 16
        }
        // About one chip for every dozen pixels scraped.
        let k = step * 0.085
        while (k > 0) {
          if (rng() < Math.min(1, k)) spawnFlakes(x, y, dx, dy, 1)
          k -= 1
        }
      }
      if (any) {
        E.dirty = true
        if (!E.started) {
          E.started = true
          anim("hint", 0, 160)
        }
        const frac = E.covered / (GX * GY)
        if (!E.revealed && frac >= props.current.threshold) doReveal(false, !E.auto.on)
      }
    }

    // request: the user earned the reveal. In controlled use it only asks the parent (onReveal)
    // and waits for the revealed prop; commit shows it.
    const doReveal = (full: boolean, request = true) => {
      if (E.revealed) return
      if (request && props.current.controlled) {
        if (full) E.wantFull = true
        if (!E.asked) {
          E.asked = true
          props.current.onReveal?.()
        }
        return
      }
      E.revealed = true
      E.started = true
      anim("hint", 0, 160)
      anim("ready", 1, 240)
      if (full) {
        E.full = true
        anim("foilA", 0, E.reduced ? 200 : 450)
      }
      E.setShown(true)
      if (request) props.current.onReveal?.()
    }
    E.doReveal = doReveal

    const doReset = (instant: boolean) => {
      E.reset = instant ? -1 : now()
      if (instant) clearAll()
      else {
        anim("maskA", 0, RESET_DUR * 1000)
        anim("hint", 1, 400)
        anim("ready", 0, 300)
        anim("copied", 0, 300)
        for (const f of E.flakes) if (f.fade >= 1) f.fade = 0.999
      }
      E.kick()
    }
    E.doReset = doReset
    const clearAll = () => {
      E.stamps = []
      E.grid.fill(0)
      E.covered = 0
      E.flakes = []
      E.started = false
      E.revealed = false
      E.full = false
      E.copied = false
      E.reset = -1
      E.asked = false
      E.wantFull = false
      const m = E.mask
      m?.getContext("2d")?.clearRect(0, 0, m.width, m.height)
      for (const [k, v] of [["hint", 1], ["ready", 0], ["copied", 0], ["foilA", 1], ["maskA", 1]] as [string, number][]) {
        const a = E.anims[k]
        a.v = a.from = a.to = v
      }
      E.dirty = true
      E.flakesDirty = true
      E.setShown(false)
      E.setCopied(false)
    }
    E.clearAll = clearAll

    // Pointer: positions in card design px.
    const toCard = (clientX: number, clientY: number) => {
      const r = root.getBoundingClientRect()
      const g = geo.current
      return [(clientX - r.left - g.cx) / g.s, (clientY - r.top - g.cy) / g.s]
    }
    const inCard = (x: number, y: number) => x >= 0 && x <= CW && y >= 0 && y <= CH

    const move = (x: number, y: number, down: boolean, t: number) => {
      const p = E.ptr
      if (p.has) {
        const dt = Math.max(1, t - p.last) / 1000
        const vx = (x - p.x) / dt
        p.vx = p.vx * 0.35 + vx * 0.65
        if (down && p.down && !E.full) scrape(p.x - PAD, p.y - PANEL_Y, x - PAD, y - PANEL_Y, Math.hypot(x - p.x, y - p.y) / dt)
      }
      p.x = x
      p.y = y
      p.last = t
      p.has = true
      p.down = down
      p.in = inCard(x, y)
      anim("coin", p.in || (down && p.kind !== "mouse") ? 1 : 0, 130)
      E.kick()
    }
    E.move = move

    const onDown = (e: PointerEvent) => {
      if (e.button !== 0 && e.pointerType === "mouse") return
      const [x, y] = toCard(e.clientX, e.clientY)
      if (!inCard(x, y)) return
      if (E.auto.on) stopAuto()
      E.ptr.kind = e.pointerType
      E.ptr.has = false
      try {
        cardRef.current?.setPointerCapture(e.pointerId)
      } catch {}
      if (e.pointerType === "mouse") e.preventDefault()
      move(x, y, true, now())
    }
    const onMove = (e: PointerEvent) => {
      if (E.auto.on) return
      const [x, y] = toCard(e.clientX, e.clientY)
      E.ptr.kind = e.pointerType
      move(x, y, E.ptr.down && (e.buttons & 1) === 1, now())
    }
    const onUp = (e: PointerEvent) => {
      if (E.auto.on) return
      const [x, y] = toCard(e.clientX, e.clientY)
      move(x, y, false, now())
      if (e.pointerType !== "mouse") anim("coin", 0, 160)
    }
    const onLeave = (e: PointerEvent) => {
      if (E.auto.on || E.ptr.down) return
      E.ptr.in = false
      anim("coin", 0, 130)
      void e
    }
    const card = cardRef.current!
    card.addEventListener("pointerdown", onDown)
    card.addEventListener("pointermove", onMove)
    card.addEventListener("pointerup", onUp)
    card.addEventListener("pointercancel", onUp)
    card.addEventListener("pointerleave", onLeave)

    const stopAuto = () => {
      E.auto.on = false
      E.auto.user = true
      E.ptr.down = false
      E.ptr.has = false
    }

    // Visibility: run only while on screen and the tab is visible.
    let visible = true
    const io = new IntersectionObserver((en) => {
      visible = en[0]?.isIntersecting ?? true
      E.kick()
    })
    io.observe(root)
    const onVis = () => E.kick()
    document.addEventListener("visibilitychange", onVis)

    let raf = 0
    let last = now()
    // While a frame runs, anything that asks for another frame only raises this flag; the end of
    // the frame schedules exactly one next frame.
    let inStep = false
    let wake = false
    const step = () => {
      raf = 0
      inStep = true
      wake = false
      const t = now()
      const dtRaw = Math.min(0.1, Math.max(0, (t - last) / 1000))
      last = t
      let busy = false

      // Autoplay drives the same handlers a hand would.
      if (E.auto.on) {
        busy = true
        const A = E.auto
        const prev = A.t
        let nt = A.t + dtRaw
        if (nt >= LOOP) {
          clearAll()
          E.rng = mulberry(7)
          A.copied = false
          nt -= LOOP
          E.ptr.has = false
        }
        const sub = Math.max(1, Math.ceil((nt - (nt < prev ? 0 : prev)) / (1 / 240)))
        const from = nt < prev ? 0 : prev
        for (let i = 1; i <= sub; i++) {
          const tt = from + ((nt - from) * i) / sub
          const [x, y] = autoPoint(tt)
          const down = tt >= AUTO_DOWN[0] && tt < AUTO_DOWN[1]
          E.ptr.kind = "mouse"
          move(x, y, down, A.base + tt * 1000)
        }
        if (nt >= AUTO_COPY && !A.copied) {
          A.copied = true
          E.copied = true
          anim("copied", 1, 250, true)
          E.setCopied(true)
        }
        if (nt >= AUTO_RESET && E.reset < 0 && E.started) doReset(false)
        A.t = nt
      }

      // Tweens.
      for (const k in E.anims) {
        const a: Anim = E.anims[k]
        if (a.v !== a.to) {
          const u = clamp((t - a.t0) / a.dur, 0, 1)
          a.v = a.from + (a.to - a.from) * (a.io ? easeInOut(u) : easeOut(u))
          if (u >= 1) a.v = a.to
          busy = true
          if (k === "foilA" || k === "maskA") E.dirty = true
        }
      }
      if (E.reset >= 0 && val("maskA", 1) <= 0) {
        clearAll()
      }

      // Coin: follows the pointer, tilts with its sideways speed, dips when pressed.
      const p = E.ptr, c = E.coin
      const g = geo.current
      const tiltTarget = E.reduced ? 0 : clamp(p.vx * 0.0062, -22, 22)
      p.vx *= Math.exp(-dtRaw * 9)
      const kk = 1 - Math.exp(-dtRaw * 16)
      c.rot += (tiltTarget - c.rot) * kk
      c.press += ((p.down ? 1 : 0) - c.press) * (1 - Math.exp(-dtRaw * 20))
      if (Math.abs(c.rot) > 0.05 || Math.abs(c.press - (p.down ? 1 : 0)) > 0.01) busy = true
      const coinEl = coinRef.current
      if (coinEl) {
        const op = val("coin")
        coinEl.style.opacity = op.toFixed(3)
        coinEl.style.visibility = op > 0.001 ? "visible" : "hidden"
        const d = COIN_D * g.s
        const x = g.cx + p.x * g.s - d / 2
        const y = g.cy + (p.y - COIN_LIFT) * g.s - d / 2
        const sc = 1 - 0.07 * c.press
        coinEl.style.transform = `translate3d(${x.toFixed(2)}px, ${y.toFixed(2)}px, 0) rotate(${c.rot.toFixed(2)}deg) scale(${sc.toFixed(4)})`
      }

      // Flakes.
      if (E.flakes.length) {
        const sub = Math.max(1, Math.ceil(dtRaw / (1 / 120)))
        const h = dtRaw / sub
        let moving = false
        const keep: Flake[] = []
        for (const f of E.flakes) {
          if (!f.rest) {
            for (let i = 0; i < sub; i++) {
              // Chips slide on the glossy card and catch on the matte page, so they pile up
              // just past the card edges.
              const onCard = f.x > 2 && f.x < CW - 2 && f.y > 2 && f.y < CH - 2
              const drag = Math.exp(-h * (onCard ? 3.2 : 20))
              f.vx *= drag
              f.vy = f.vy * drag + 40 * h
              f.x += f.vx * h
              f.y += f.vy * h
              f.r += f.vr * h
              f.vr *= drag
            }
            f.age += dtRaw
            if (f.age > 0.45 && Math.hypot(f.vx, f.vy) < 26) f.rest = true
            moving = true
          }
          if (f.fade < 1) {
            f.fade -= dtRaw / 0.6
            moving = true
          }
          if (f.fade > 0) keep.push(f)
        }
        E.flakes = keep
        if (moving) {
          busy = true
          E.flakesDirty = true
        }
      }

      if (E.flakesDirty) {
        E.flakesDirty = false
        const fc = flakeRef.current
        const ctx = fc?.getContext("2d")
        if (fc && ctx) {
          const dpr = E.dpr || 1
          ctx.setTransform(1, 0, 0, 1, 0, 0)
          ctx.clearRect(0, 0, fc.width, fc.height)
          const k = g.s * dpr
          for (const f of E.flakes) {
            const cr = Math.cos(f.r), sr = Math.sin(f.r)
            ctx.setTransform(cr * k, sr * k, -sr * k, cr * k, (g.cx + f.x * g.s) * dpr, (g.cy + f.y * g.s) * dpr)
            ctx.globalAlpha = 0.92 * Math.max(0, f.fade)
            ctx.fillStyle = f.col
            const w = Math.max(f.w, 0.9 / g.s)
            ctx.fillRect(-f.len / 2, -w / 2, f.len, w)
          }
          ctx.globalAlpha = 1
          ctx.setTransform(1, 0, 0, 1, 0, 0)
        }
      }

      // Foil = texture minus the scratch mask.
      if (E.dirty) {
        E.dirty = false
        const fc = foilRef.current
        const ctx = fc?.getContext("2d")
        if (fc && ctx && E.texture) {
          ctx.globalCompositeOperation = "copy"
          ctx.globalAlpha = val("foilA", 1)
          ctx.drawImage(E.texture, 0, 0, fc.width, fc.height)
          if (E.mask && E.stamps.length) {
            ctx.globalCompositeOperation = "destination-out"
            ctx.globalAlpha = val("maskA", 1)
            ctx.drawImage(E.mask, 0, 0)
          }
          ctx.globalCompositeOperation = "source-over"
          ctx.globalAlpha = 1
        }
      }

      // Hint row and copy button.
      const hA = val("hint", 1), rA = val("ready"), cA = val("copied")
      const hintEl = hintRef.current
      if (hintEl) {
        hintEl.style.opacity = hA.toFixed(3)
        hintEl.style.visibility = hA > 0.001 ? "visible" : "hidden"
      }
      const readyEl = readyRef.current
      if (readyEl) {
        readyEl.style.opacity = rA.toFixed(3)
        readyEl.style.visibility = rA > 0.001 ? "visible" : "hidden"
        readyEl.style.transform = `translate(-50%, -50%) translateY(${((1 - rA) * 5 * g.s).toFixed(2)}px)`
      }
      const btn = btnRef.current
      if (btn) {
        btn.style.background = css(mix(parseColor(props.current.textColor), parseColor(props.current.success), cA))
        const l1 = lab1Ref.current, l2 = lab2Ref.current
        const dy = 15 * g.s
        if (l1) {
          l1.style.opacity = (1 - cA).toFixed(3)
          l1.style.transform = `translateY(${(-cA * dy).toFixed(2)}px)`
        }
        if (l2) {
          l2.style.opacity = cA.toFixed(3)
          l2.style.transform = `translateY(${((1 - cA) * dy).toFixed(2)}px)`
        }
      }

      inStep = false
      if ((busy || wake || E.dirty || E.flakesDirty) && visible && !document.hidden && !raf) raf = requestAnimationFrame(step)
    }
    E.kick = () => {
      if (inStep) {
        wake = true
        return
      }
      if (!raf && visible && !document.hidden) {
        last = now()
        raf = requestAnimationFrame(step)
      }
    }
    E.kick()

    return () => {
      if (raf) cancelAnimationFrame(raf)
      io.disconnect()
      document.removeEventListener("visibilitychange", onVis)
      mq?.removeEventListener?.("change", onMq)
      card.removeEventListener("pointerdown", onDown)
      card.removeEventListener("pointermove", onMove)
      card.removeEventListener("pointerup", onUp)
      card.removeEventListener("pointercancel", onUp)
      card.removeEventListener("pointerleave", onLeave)
      E.kick = () => {}
    }
  }, [])

  // Autoplay on and off.
  React.useEffect(() => {
    const E = eng.current
    if (autoplay) {
      E.clearAll?.()
      E.rng = mulberry(7)
      E.auto = { on: true, t: 0, user: false, copied: false, base: performance.now() }
      E.ptr.has = false
      E.kick()
    } else if (!autoplay && E.auto.on) {
      E.auto.on = false
      E.ptr.down = false
      E.anim?.("coin", 0, 130)
    }
  }, [autoplay])

  // Controlled reveal.
  React.useEffect(() => {
    const E = eng.current
    // Commit a reveal the parent asked for: keep the scratches if the card was scratched open,
    // clear the foil if it was revealed by keyboard or from outside.
    if (revealed === true && !E.revealed) E.doReveal?.(!!E.wantFull || !E.asked, false)
    if (revealed === false && E.revealed) E.doReset?.(false)
  }, [revealed])

  // Copied returns to Copy after a while.
  React.useEffect(() => {
    if (!copied || !copiedDuration || eng.current.auto.on) return
    const id = setTimeout(() => {
      eng.current.copied = false
      eng.current.anim?.("copied", 0, 250, true)
      setCopied(false)
    }, copiedDuration)
    return () => clearTimeout(id)
  }, [copied, copiedDuration, copyTick])

  const copy = React.useCallback(async () => {
    const E = eng.current
    let ok = false
    try {
      if (navigator.clipboard?.writeText) {
        await navigator.clipboard.writeText(code)
        ok = true
      }
    } catch {}
    if (!ok) {
      try {
        const ta = document.createElement("textarea")
        ta.value = code
        ta.setAttribute("readonly", "")
        ta.style.position = "fixed"
        ta.style.opacity = "0"
        document.body.appendChild(ta)
        ta.select()
        ok = document.execCommand("copy")
        document.body.removeChild(ta)
      } catch {}
    }
    E.copied = true
    E.anim?.("copied", 1, 250, true)
    setCopied(true)
    setCopyTick((n) => n + 1)
    if (ok) onCopy?.(code)
  }, [code, onCopy])

  const onPanelKey = (e: React.KeyboardEvent) => {
    if (isRevealed) return
    if (e.key === "Enter" || e.key === " " || e.key === "Spacebar") {
      e.preventDefault()
      eng.current.doReveal?.(true)
      // Hand keyboard focus on to the copy button once it has faded in.
      setTimeout(() => {
        const b = btnRef.current
        if (b && b.style.visibility !== "hidden" && document.activeElement === panelRef.current) b.focus()
      }, 320)
    }
  }

  const z = (n: number) => `${(n * s).toFixed(2)}px`
  const fs = (n: number, floor = 11) => `${Math.max(floor, n * s).toFixed(2)}px`
  const inkRGB = parseColor(ink)
  const colorRGB = parseColor(color)
  const coinRGB = parseColor(coin)
  const coinHi = css(mix(coinRGB, WHITE, 0.38))
  const coinMid = css(coinRGB)
  const coinLo = css(mix(coinRGB, BLACK, 0.07))
  const coinRim = css(mix(coinRGB, BLACK, 0.3))
  const coinEdge = css(mix(coinRGB, BLACK, 0.12))
  const coinEngrave = css(mix(coinRGB, BLACK, 0.36))
  const muted = css(mix(parseColor(background), parseColor(textColor), 0.58))
  const soft = css(mix(colorRGB, inkRGB, 0.58))
  const sh = mix(mix(parseColor(background), BLACK, 0.62), colorRGB, 0.06)

  return (
    <div
      ref={rootRef}
      className={className}
      style={{
        position: "relative",
        width: "100%",
        height: "100%",
        minHeight: 380,
        overflow: "hidden",
        background,
        fontFamily: font,
        WebkitFontSmoothing: "antialiased",
        ...style,
      }}
      {...rest}
    >
      <style>{`
.lsk${uid}-panel:focus{outline:none}
.lsk${uid}-panel[role=button]:focus-visible{box-shadow:0 0 0 ${z(2.5)} ${css(colorRGB)},0 0 0 ${z(5)} ${css(inkRGB, 0.95)}}
.lsk${uid}-btn{outline:none}
.lsk${uid}-btn:focus-visible{box-shadow:0 0 0 ${z(2.5)} ${background},0 0 0 ${z(4.5)} ${css(parseColor(textColor), 0.85)}}
.lsk${uid}-sr{position:absolute;width:1px;height:1px;padding:0;margin:-1px;overflow:hidden;clip:rect(0 0 0 0);white-space:nowrap;border:0}
`}</style>
      {(
        <>
          <div
            ref={cardRef}
            role="group"
            aria-label={[amount, brand, "gift card"].filter(Boolean).join(" ")}
            style={{
              position: "absolute",
              left: cx,
              top: cy,
              width: cw,
              height: ch,
              borderRadius: z(CARD_R),
              background: color,
              color: ink,
              userSelect: "none",
              WebkitUserSelect: "none",
              cursor: "none",
              touchAction: "pan-y",
              boxShadow: `inset 0 ${z(1)} 0 ${css(inkRGB, 0.32)}, inset 0 0 0 ${z(1)} ${css(inkRGB, 0.1)}, 0 ${z(2)} ${z(3)} ${css(sh, 0.45)}, 0 ${z(13)} ${z(20)} ${z(-6)} ${css(sh, 0.6)}, 0 ${z(34)} ${z(56)} ${z(-12)} ${css(sh, 0.36)}`,
            }}
          >
            <div
              style={{
                position: "absolute",
                left: z(35),
                top: z(32),
                right: z(170),
                lineHeight: 1.15,
                whiteSpace: "nowrap",
                overflow: "hidden",
                textOverflow: "ellipsis",
              }}
            >
              <div style={{ fontSize: fs(16.5), fontWeight: 650, letterSpacing: "-0.005em" }}>{brand}</div>
              <div style={{ fontSize: fs(14), fontWeight: 400, color: soft, marginTop: z(1.5) }}>{tagline}</div>
            </div>
            <svg
              aria-hidden="true"
              viewBox={MARK_VIEWBOX}
              style={{ position: "absolute", right: z(37), top: z(25), width: z(78), height: z(80), overflow: "visible" }}
            >
              <path fill={ink} d={MARK_PATH} />
            </svg>
            <div
              style={{
                position: "absolute",
                left: z(26),
                top: z(78),
                fontFamily: amountFont,
                fontStretch: "condensed",
                fontWeight: 900,
                fontSize: z(140),
                lineHeight: 1,
                letterSpacing: "-0.032em",
                whiteSpace: "nowrap",
              }}
            >
              {amount}
            </div>
            <div
              style={{
                position: "absolute",
                left: z(35),
                right: z(35),
                top: z(238),
                fontSize: fs(14),
                lineHeight: 1.3,
                color: soft,
                whiteSpace: "nowrap",
                overflow: "hidden",
                textOverflow: "ellipsis",
              }}
            >
              {note}
            </div>
            <div
              ref={panelRef}
              className={`lsk${uid}-panel`}
              role={isRevealed ? "group" : "button"}
              tabIndex={isRevealed ? -1 : 0}
              aria-label={isRevealed ? "Gift card code" : revealLabel}
              onKeyDown={onPanelKey}
              onClick={(e) => {
                // A click with no drag from a screen reader or switch control reveals too.
                if (e.detail === 0 && !isRevealed) eng.current.doReveal?.(true)
              }}
              style={{
                position: "absolute",
                left: z(PAD),
                top: z(PANEL_Y),
                width: z(PANEL_W),
                height: z(PANEL_H),
                borderRadius: z(PANEL_R),
                background: paper,
                touchAction: "none",
                overflow: "hidden",
              }}
            >
              <div
                aria-hidden={!isRevealed}
                style={{
                  position: "absolute",
                  inset: 0,
                  display: "flex",
                  alignItems: "center",
                  justifyContent: "center",
                  paddingTop: z(4),
                  fontFamily: codeFont,
                  fontWeight: 600,
                  fontSize: fs(31, 13),
                  letterSpacing: "0.07em",
                  textIndent: "0.07em",
                  color: textColor,
                  whiteSpace: "nowrap",
                }}
              >
                {code}
              </div>
              <canvas
                ref={foilRef}
                aria-hidden="true"
                style={{ position: "absolute", inset: 0, width: "100%", height: "100%", display: "block" }}
              />
            </div>
          </div>
          <canvas
            ref={flakeRef}
            aria-hidden="true"
            style={{ position: "absolute", left: 0, top: 0, width: W, height: H, pointerEvents: "none" }}
          />
          <div
            ref={coinRef}
            aria-hidden="true"
            style={{
              position: "absolute",
              left: 0,
              top: 0,
              width: z(COIN_D),
              height: z(COIN_D),
              pointerEvents: "none",
              opacity: 0,
              visibility: "hidden",
              willChange: "transform, opacity",
              filter: `drop-shadow(${z(1.5)} ${z(3)} ${z(2.5)} ${css(mix(coinRGB, BLACK, 0.75), 0.42)})`,
