                  <stop offset="0" stopColor={coinHi} />
                  <stop offset="0.55" stopColor={coinMid} />
                  <stop offset="1" stopColor={coinLo} />
                </radialGradient>
                <linearGradient id={`lsk${uid}r`} x1="0.2" y1="0" x2="0.8" y2="1">
                  <stop offset="0" stopColor={coinEdge} />
                  <stop offset="1" stopColor={coinRim} />
                </linearGradient>
              </defs>
              <circle cx="26" cy="26" r="25.5" fill={coinRim} />
              <circle cx="26" cy="26" r="24" fill={`url(#lsk${uid}r)`} />
              <circle cx="26" cy="26" r="22.8" fill={`url(#lsk${uid}f)`} />
              <circle cx="26" cy="26" r="22.8" fill="none" stroke={coinRim} strokeOpacity="0.5" strokeWidth="0.8" />
              <path
                d="M22.6 22.4 L27.4 18.8 L27.4 33.4"
                fill="none"
                stroke={coinHi}
                strokeOpacity="0.7"
                strokeWidth="2.6"
                strokeLinecap="round"
                strokeLinejoin="round"
                transform="translate(0.6 0.7)"
              />
              <path
                d="M22.6 22.4 L27.4 18.8 L27.4 33.4"
                fill="none"
                stroke={coinEngrave}
                strokeWidth="2.6"
                strokeLinecap="round"
                strokeLinejoin="round"
              />
            </svg>
          </div>
          <div
            ref={hintRef}
