          <div
            ref={readyRef}
            style={{
              position: "absolute",
              left: cx + cw / 2,
              top: cy + READY_Y * s,
              transform: "translate(-50%, -50%) translateY(5px)",
              display: "flex",
              alignItems: "center",
              gap: z(20),
              whiteSpace: "nowrap",
              opacity: 0,
              visibility: "hidden",
            }}
          >
            <span aria-hidden="true" style={{ fontSize: fs(18), color: muted }}>
              {readyHint}
            </span>
            <button
              ref={btnRef}
              type="button"
              className={`lsk${uid}-btn`}
              tabIndex={isRevealed ? 0 : -1}
              aria-hidden={!isRevealed}
              onClick={copy}
              style={{
                position: "relative",
                height: Math.max(32, 48 * s),
                padding: `0 ${z(22)}`,
                minWidth: z(130),
                border: 0,
                borderRadius: 999,
                background: textColor,
                color: "#ffffff",
                font: "inherit",
                fontSize: fs(16),
                fontWeight: 600,
                cursor: "pointer",
                overflow: "hidden",
              }}
            >
              <span ref={lab1Ref} aria-hidden={copied} style={{ display: "block" }}>
                {copyLabel}
              </span>
              <span
                ref={lab2Ref}
                aria-hidden={!copied}
                style={{
                  position: "absolute",
